create extension if not exists pgcrypto;

create table if not exists public.farms(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) on delete cascade,name text not null,location text,area_acres numeric(10,2),latitude double precision,longitude double precision,created_at timestamptz not null default now());
create table if not exists public.zones(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id) on delete cascade,name text not null,crop_name text,status text not null default 'healthy' check(status in('healthy','attention','critical')),moisture_target_min numeric(5,2) default 35,moisture_target_max numeric(5,2) default 70,area_acres numeric(10,2),polygon jsonb,created_at timestamptz not null default now());
create table if not exists public.sensor_readings(id bigint generated always as identity primary key,zone_id uuid not null references public.zones(id) on delete cascade,moisture numeric(5,2),temperature numeric(6,2),humidity numeric(5,2),water_level numeric(5,2),recorded_at timestamptz not null default now());
create index if not exists sensor_readings_zone_time on public.sensor_readings(zone_id,recorded_at desc);
create table if not exists public.crops(id uuid primary key default gen_random_uuid(),name text not null,variety text,growth_stage text,soil_ph_min numeric(4,2),soil_ph_max numeric(4,2),water_need text,fertilizer text,season text,notes text,created_at timestamptz not null default now());
create table if not exists public.crop_observations(id uuid primary key default gen_random_uuid(),zone_id uuid references public.zones(id) on delete cascade,image_url text,diagnosis text,confidence numeric(5,2),severity text,advice text,created_at timestamptz not null default now());
create table if not exists public.irrigation_events(id bigint generated always as identity primary key,zone_id uuid not null references public.zones(id) on delete cascade,mode text not null default 'auto',action text not null,duration_seconds integer,reason text,created_at timestamptz not null default now());
create table if not exists public.equipment(id uuid primary key default gen_random_uuid(),farm_id uuid references public.farms(id) on delete cascade,name text not null,category text not null,status text not null default 'available',image_url text,specifications jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.market_prices(id bigint generated always as identity primary key,crop_name text not null,market_name text,state text,price_per_quintal numeric(12,2) not null,change_percent numeric(7,2) default 0,recorded_on date not null default current_date,source text);
create table if not exists public.alerts(id uuid primary key default gen_random_uuid(),farm_id uuid references public.farms(id) on delete cascade,zone_id uuid references public.zones(id) on delete cascade,type text not null,title text not null,message text,is_read boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.ai_conversations(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,farm_id uuid references public.farms(id) on delete set null,title text not null default 'New conversation',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ai_messages(id bigint generated always as identity primary key,conversation_id uuid not null references public.ai_conversations(id) on delete cascade,role text not null,content text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());

alter table public.farms enable row level security; alter table public.zones enable row level security; alter table public.sensor_readings enable row level security; alter table public.crops enable row level security; alter table public.crop_observations enable row level security; alter table public.irrigation_events enable row level security; alter table public.equipment enable row level security; alter table public.market_prices enable row level security; alter table public.alerts enable row level security; alter table public.ai_conversations enable row level security; alter table public.ai_messages enable row level security;

create policy farms_owner on public.farms for all to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy zones_owner on public.zones for all to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid()))) with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy sensors_owner on public.sensor_readings for all to authenticated using(exists(select 1 from public.zones z join public.farms f on f.id=z.farm_id where z.id=zone_id and f.owner_id=(select auth.uid()))) with check(exists(select 1 from public.zones z join public.farms f on f.id=z.farm_id where z.id=zone_id and f.owner_id=(select auth.uid())));
create policy crops_public_read on public.crops for select to anon,authenticated using(true);
create policy market_public_read on public.market_prices for select to anon,authenticated using(true);
create policy observations_owner on public.crop_observations for all to authenticated using(exists(select 1 from public.zones z join public.farms f on f.id=z.farm_id where z.id=zone_id and f.owner_id=(select auth.uid()))) with check(exists(select 1 from public.zones z join public.farms f on f.id=z.farm_id where z.id=zone_id and f.owner_id=(select auth.uid())));
create policy irrigation_owner on public.irrigation_events for all to authenticated using(exists(select 1 from public.zones z join public.farms f on f.id=z.farm_id where z.id=zone_id and f.owner_id=(select auth.uid()))) with check(exists(select 1 from public.zones z join public.farms f on f.id=z.farm_id where z.id=zone_id and f.owner_id=(select auth.uid())));
create policy equipment_owner on public.equipment for all to authenticated using(farm_id is null or exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid()))) with check(farm_id is null or exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy alerts_owner on public.alerts for all to authenticated using(farm_id is null or exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid()))) with check(farm_id is null or exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy conversations_owner on public.ai_conversations for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy messages_owner on public.ai_messages for all to authenticated using(exists(select 1 from public.ai_conversations c where c.id=conversation_id and c.user_id=(select auth.uid()))) with check(exists(select 1 from public.ai_conversations c where c.id=conversation_id and c.user_id=(select auth.uid())));

insert into public.crops(name,variety,growth_stage,soil_ph_min,soil_ph_max,water_need,fertilizer,season) select * from (values ('Rice','ADT 53','Vegetative',5.5,7.0,'High','NPK 100:50:50','Samba'),('Tomato','Hybrid','Flowering',6.0,7.5,'Medium','NPK 80:40:60','Year-round'),('Onion','CO 5','Bulb development',6.0,7.5,'Medium','NPK 60:40:60','Rabi')) v(name,variety,growth_stage,soil_ph_min,soil_ph_max,water_need,fertilizer,season) where not exists(select 1 from public.crops);
insert into public.market_prices(crop_name,market_name,state,price_per_quintal,change_percent,source) select * from (values ('Paddy','Coimbatore','Tamil Nadu',2320,2.1,'Demo'),('Tomato','Coimbatore','Tamil Nadu',1800,-1.3,'Demo'),('Onion','Coimbatore','Tamil Nadu',1600,.8,'Demo'),('Chili','Dindigul','Tamil Nadu',4500,2.4,'Demo'),('Maize','Coimbatore','Tamil Nadu',1850,1.2,'Demo')) v(crop_name,market_name,state,price_per_quintal,change_percent,source) where not exists(select 1 from public.market_prices);
